jQuery(document).ready(function($){
	if($('.reference-score-wrapper').length || $('.my-score-wrapper').length) {
		updateOverallScore();

		$('.score-display .edit-score-button').on('click', function(){
			const parentDiv = $(this).closest('.score-display');

			parentDiv.addClass('editing');
		});	
		$('.score-display .cancel-edit-score').on('click', function(){
			const parentDiv = $(this).closest('.score-display');

			parentDiv.removeClass('editing');
		});	

		$('.my-score-wrapper .score-display .score-edit .submit-score-edit').on('click', function(e){
			e.preventDefault();

			const parentDiv = $(this).closest('.score-edit');

			const songId = parentDiv.attr('song_id');
			const judgeId = parentDiv.attr('judge_id');

			const score = parentDiv.find('input.score-value').val();
			const comments = parentDiv.find('textarea.score-comments').val();
			const penalty = parentDiv.hasClass('showing-penalty') ? parentDiv.find('textarea.score-penalty').val() : '';

			if(!score || score < 0 || score > 100) {
				if(!score) {
					window.alert('Score is required to submit');
				} else if(!score || score < 0 || score > 100) {
					window.alert('Score must be between 0 and 100');
				}
				return;
			}

			const data = {
				action: 'bbs_submit_score',
				song_id: songId,
				judge_id: judgeId,
				score: score,
				comments: comments,
				penalty: penalty,
			};
			console.log(data);

			$.post('/wp-admin/admin-ajax.php', data, function(response){
				console.log(response);
				const responseJson = JSON.parse(response);
				console.log(responseJson);
			});
		});	

		$('.my-score-wrapper .show-score-penalty').on('click', function(e){
			$(this).closest('.score-edit').toggleClass('showing-penalty');
		});	

		$('.reference-score-wrapper .score-display .score-edit .submit-score-edit').on('click', function(){
			updateReferenceScore($(this).closest('.score-edit'));
		});	

		$('.reference-score-wrapper .score-display .score-edit .score-value').on('keydown', function(e){
			if(e.originalEvent.key == 'Enter') {
				e.preventDefault();
				updateReferenceScore($(this).closest('.score-edit'));
			}
		});	

		$('.reference-score-wrapper.contest-scores .score-display .score-edit .score-value').on('keydown', function(e){
			if(e.originalEvent.key == 'Enter') {
				e.preventDefault();
			}

			const el = $(this);
			setTimeout(function(){
				el.closest('.score-display').attr('score', el.val());
				updateOverallScore();
			}, 500);
		});	

		function updateReferenceScore(el) {
			const parentDiv = el.closest('.score-display');

			const category = el.attr('category');
			const input = el.find('input[category="' + category + '"]');
			const value = input.val();
			const postId = parentDiv.attr('post_id');

			console.log(value);

			if(value || value === '0') {
				input.val('');
				parentDiv.removeClass('editing');
				parentDiv.find('.score-view').html('<span class="fas fa-cog fa-spin"></span>');

				const data = {
					action: 'bbs_update_reference_score',
					category: category,
					score: value,
					post_id: postId,
					time: Date.now(),
				};
				console.log(data);

				$.post('/wp-admin/admin-ajax.php', data, function(response){
					console.log(response);
					responseJson = JSON.parse(response);
					console.log(responseJson);
	
					parentDiv.attr('score', responseJson.score);
					parentDiv.find('.history.scfe-modal-trigger').attr('update_history', btoa(JSON.stringify(responseJson.score_history)));
					parentDiv.find('.score-view').html(responseJson.score);

					parentDiv.closest('.reference-score-wrapper').find('.score-display.overall .score-view').html('<span class="fas fa-cog fa-spin"></span>');
					setTimeout(function(){
						updateOverallScore();
					}, 300);
				});
			} else {
				window.alert('Please enter a value before submitting');
			}
		}

		$('.score-display .history.scfe-modal-trigger').on('click', function(){
			const target = $(this).attr('target');
			const category = $(this).attr('category');

			const history = $(this).attr('update_history');
			console.log(history);
			const historyStr = atob(history);
			console.log(historyStr);
			const historyJson = JSON.parse(historyStr);
			console.log(historyJson);

			let html = '';
			html += '<tr><th>Score</th><th>Updated By</th><th>Timestamp</th></tr>';
			$.each(historyJson, function(i, entry){
				console.log(i, entry)
				if(entry.type == 'contest_score') {
					html += '<tr class="contest-score"><td>' + entry.score + '</td><td colspan="2">Contest Score</td></tr>';
				} else {
					html += '<tr><td>' + entry.score + '</td><td>' + entry.updated_by + '</td><td>' + entry.timestamp + '</td></tr>';
				}
			})

			html = '<table class="reference-score-table ' + category + '">' + html + '</table>';

			$(target + ' .scfe-modal-body').html(html);
		});	

		function updateOverallScore() {
			$('.reference-score-wrapper').each(function(){
				const wrapperDiv = $(this);

				let totalScore = 0;
				let hasAllScores = true;

				const scoreDisplays = $(this).find('.score-display[score]');

				scoreDisplays.each(function(){
					const score = $(this).attr('score');
					if(score || score === '0') {
						totalScore += parseFloat(score);
					} else {
						hasAllScores = false;
						$(this).addClass('editing');
					}
				});

				let avgScore = 'No data';
				if(hasAllScores) {
					avgScore = Math.round(totalScore * 10 / scoreDisplays.length) / 10;
				}

				wrapperDiv.find('.score-display.overall .score-view').html(avgScore);
			});
		}
	}

});
jQuery(document).ready(function($){
	$('input.datepicker-frontend').on('focus', function(e){
		let el = $(this);
		if (!el.hasClass('hasDatepicker')) {
			el.datepicker({
				showOtherMonths: true,
				dateFormat: 'm/d/yy',
				altFormat: 'yymmdd',
				changeMonth: true,
				changeYear: true,
				yearRange: 'c-100:c+5',
				beforeShow: function(input, inst) {
					inst.dpDiv.addClass('sc-field-editor-datepicker');
				},
				onSelect: function(value, datepicker) {
					let altFormat = datepicker.selectedYear.toString() + zeroPad(datepicker.selectedMonth + 1) + zeroPad(datepicker.selectedDay);
					let hiddenField = $(this).closest('.input-wrapper').find('.datepicker-value');
					console.log(altFormat);
					hiddenField.val(altFormat);
					el.change();
				}
			});
		}

		el.datepicker('show');
	});

	$('input.datepicker-frontend').on('change', function(){
		let el = $(this);
		
		let hiddenValue = '';
		if($(this).val()) {
			const [month, day, year] = $(this).val().split('/');
			hiddenValue = `${year}${month.padStart(2, '0')}${day.padStart(2, '0')}`;
		}

		$(this).closest('.input-wrapper').find('.datepicker-value').val(hiddenValue).change();
		setTimeout(function(){
			el.datepicker('destroy');
		}, 200);
	});

	function zeroPad(num) {
		var zero = 2 - num.toString().length + 1;
		return Array(+(zero > 0 && zero)).join("0") + num;		
	}
});
